// Packaging only: crop cells, apply one uniform scale per clip, align feet, pack PNGs.
// Character drawings are generated by image_gen; this script does not draw or deform them.
const fs=require('node:fs');
const path=require('node:path');
const sharp=require('sharp');
const root=path.resolve(__dirname,'..');
const metrics=JSON.parse(fs.readFileSync(path.join(root,'QA/source-metrics.json'),'utf8'));
const SIZE=512, FOOT_Y=479, FOOT_X=285.5;
const clips={
 idle:{cols:4,rows:2,delay:[300,200,250,70,80,70,230,300],loop:true},
 think:{cols:4,rows:3,delay:[120,120,140,180,260,140,160,260,100,140,160,220],loop:true}
};
const transparent={r:0,g:0,b:0,alpha:0};
function bounds(data,w,h,threshold=32) {
 let x0=w,y0=h,x1=-1,y1=-1;const hist=Array(256).fill(0);
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){
  const a=data[(y*w+x)*4+3];hist[a]++;
  if(a>=threshold){x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);}
 }
 let fx0=w,fx1=-1;
 for(let y=Math.max(0,y1-8);y<=y1;y++)for(let x=0;x<w;x++)if(data[(y*w+x)*4+3]>=128){fx0=Math.min(fx0,x);fx1=Math.max(fx1,x);}
 return {bbox:[x0,y0,x1,y1],footCenter:(fx0+fx1)/2,alphaHistogram:hist};
}
async function makeGif(pngs,delays,out,bg='#172732',size=384){
 const rasters=[];
 for(const png of pngs)rasters.push(await sharp(png).resize(size,size).flatten({background:bg}).raw().toBuffer());
 await sharp(Buffer.concat(rasters),{raw:{width:size,height:size*rasters.length,channels:3,pageHeight:size}})
 .gif({delay:delays,loop:0,effort:7,dither:0}).toFile(out);
 return sharp(out,{animated:true}).metadata();
}
(async()=>{
 for(const dir of ['Source','Sprites/Idle','Sprites/Think','Sheets','Previews','QA'])fs.mkdirSync(path.join(root,dir),{recursive:true});
 fs.copyFileSync(metrics.reference.source,path.join(root,'Source','original_player_idle_00.png'));
 const rawGenerated='C:/Users/10029/.codex/generated_images/01a171d5-ad4b-7063-81ea-324c6e8c91ba/exec-c3d47427-3802-4e1b-a9b3-330501b19813.png';
 fs.copyFileSync(rawGenerated,path.join(root,'Source','think_first_draft.png'));
 const all={},qa={frames:[],gifs:{},method:'Uniform scale per clip and foot registration; original drawing pixels retained. Clip endpoints reuse idle_00.'};
 const referenceHeight=380;
 for(const [name,c] of Object.entries(clips)){
  const source=metrics[name],first=source.frames[0];
  const scale=referenceHeight/(first.bbox[3]-first.bbox[1]+1);
  fs.copyFileSync(source.source,path.join(root,'Source',name+'_generated.png'));
  const frames=[];
  for(let i=0;i<c.cols*c.rows;i++){
   const m=source.frames[i];
   const cellX=Math.round(i%c.cols*source.width/c.cols),cellY=Math.round(Math.floor(i/c.cols)*source.height/c.rows);
   // Trim only transparent gutters: use a four-pixel margin around the visible alpha bounds.
   const x=Math.max(0,m.bbox[0]-4),y=Math.max(0,m.bbox[1]-4);
   const r=Math.min(m.w,m.bbox[2]+5),b=Math.min(m.h,m.bbox[3]+5);
   const raster=await sharp(source.source).extract({left:cellX+x,top:cellY+y,width:r-x,height:b-y})
    .resize(Math.round((r-x)*scale),Math.round((b-y)*scale),{kernel:'lanczos3'}).ensureAlpha().raw().toBuffer({resolveWithObject:true});
   const bm=bounds(raster.data,raster.info.width,raster.info.height);
   const left=Math.round(FOOT_X-bm.footCenter),top=FOOT_Y-bm.bbox[3];
   if(left<0||top<0||left+raster.info.width>512||top+raster.info.height>512)throw new Error('Clipped sprite '+name+i);
   const png=await sharp({create:{width:512,height:512,channels:4,background:transparent}})
    .composite([{input:raster.data,raw:{width:raster.info.width,height:raster.info.height,channels:4},left,top}]).png().toBuffer();
   frames.push(png);
  }
  if(name==='idle')frames[7]=frames[0];
  if(name==='think'){frames[0]=all.idle[0];frames[11]=all.idle[0];}
  all[name]=frames;
  for(let i=0;i<frames.length;i++){
   const stem='player_'+name+'_'+String(i).padStart(2,'0')+'.png';
   fs.writeFileSync(path.join(root,'Sprites',name==='idle'?'Idle':'Think',stem),frames[i]);
   const data=await sharp(frames[i]).ensureAlpha().raw().toBuffer();
   const m=bounds(data,512,512);let edge=0;
   for(let z=0;z<512;z++)for(const p of [z,511*512+z,z*512,z*512+511])if(data[p*4+3]>0)edge++;
   qa.frames.push({clip:name,index:i,size:[512,512],...m,edgeNontransparent:edge});
  }
  await sharp({create:{width:c.cols*512,height:c.rows*512,channels:4,background:transparent}})
   .composite(frames.map((input,i)=>({input,left:i%c.cols*512,top:Math.floor(i/c.cols)*512})))
   .png().toFile(path.join(root,'Sheets','player_'+name+'_grid.png'));
  await sharp({create:{width:frames.length*512,height:512,channels:4,background:transparent}})
   .composite(frames.map((input,i)=>({input,left:i*512,top:0})))
   .png().toFile(path.join(root,'Sheets','player_'+name+'_strip.png'));
  qa.gifs[name]=await makeGif(frames,c.delay,path.join(root,'Previews',name+'.gif'));
 }
 const autoFrames=[...all.idle,...all.idle,...all.think];
 const autoDelay=[...clips.idle.delay,...clips.idle.delay,...clips.think.delay];
 qa.gifs.auto=await makeGif(autoFrames,autoDelay,path.join(root,'Previews','idle_3s_then_think.gif'));
 const sample=(name,t)=>{const d=clips[name].delay,total=d.reduce((a,b)=>a+b,0);let p=t%total;for(let i=0;i<d.length;i++){if(p<d[i])return i;p-=d[i];}return 0;};
 const points=new Set([0,6000]);
 for(const [name,c] of Object.entries(clips)){
  const total=c.delay.reduce((a,b)=>a+b,0);
  for(let base=0;base<6000;base+=total){let t=base;for(const d of c.delay){points.add(t);t+=d;}points.add(t);}
 }
 const events=Array.from({length:151},(_,i)=>i*40),compare=[],compareDelays=[];
 const heading=Buffer.from('<svg width="768" height="440"><style>text{font-family:Arial,sans-serif;font-weight:600;fill:#dce7ec;font-size:18px}</style><text x="32" y="36">IDLE</text><text x="416" y="36">THINK / AFTER 3s</text><path d="M384 64V410" stroke="#304450"/></svg>');
 for(let i=0;i<events.length-1;i++){
  const inputs=[];
  for(const [j,name] of ['idle','think'].entries()){
   const sprite=await sharp(all[name][sample(name,events[i])]).resize(384,384).toBuffer();
   inputs.push({input:sprite,left:j*384,top:50});
  }
  const raw=await sharp({create:{width:768,height:440,channels:4,background:'#172732'}})
   .composite([{input:heading,left:0,top:0},...inputs]).removeAlpha().raw().toBuffer();
  compare.push(raw);compareDelays.push(events[i+1]-events[i]);
 }
 await sharp(Buffer.concat(compare),{raw:{width:768,height:440*compare.length,channels:3,pageHeight:440}})
 .gif({delay:compareDelays,loop:0,effort:7,dither:0}).toFile(path.join(root,'Previews','comparison.gif'));
 qa.gifs.comparison=await sharp(path.join(root,'Previews','comparison.gif'),{animated:true}).metadata();
 const manifest={
  name:'LightHungry Player Idle v02',date:'2026-10-25',generator:'built-in image_gen',
  frameSize:[512,512],facing:'right',pixelsPerUnit:256,pivot:[0.5,0.0625],footReferenceY:480,
  alpha:'RGBA PNG; generated alpha preserved through slicing and resizing.',
  playback:{idleThresholdSeconds:3,thinkingLoopsWhileIdle:true,interruptImmediatelyOn:['move','jump','interact','ability','damage','death'],timerReset:'Any gameplay action or leaving grounded neutral state.'},
  clips:Object.fromEntries(Object.entries(clips).map(([name,c])=>[name,{
   frameCount:all[name].length,loop:c.loop,durationMs:c.delay.reduce((a,b)=>a+b,0),
   frameDurationMs:c.delay,grid:'Sheets/player_'+name+'_grid.png',gridLayout:[c.cols,c.rows],
   horizontalStrip:'Sheets/player_'+name+'_strip.png',
   frames:all[name].map((_,i)=>'Sprites/'+(name==='idle'?'Idle':'Think')+'/player_'+name+'_'+String(i).padStart(2,'0')+'.png'),
   endpointReuse:name==='idle'?'Frame 07 is frame 00.':'Frames 00 and 11 reuse idle frame 00.'
  }]))
 };
 fs.writeFileSync(path.join(root,'animations.json'),JSON.stringify(manifest,null,2));
 qa.checks={
  frameCount:qa.frames.length===20,
  everyFrameTransparent:qa.frames.every(f=>f.alphaHistogram[0]>100000),
  everyFrameVisible:qa.frames.every(f=>f.alphaHistogram.slice(128).reduce((a,b)=>a+b,0)>50000),
  feetAligned:qa.frames.every(f=>f.bbox[3]===479&&Math.abs(f.footCenter-285.5)<=1),
  noFrameEdgeClipping:qa.frames.every(f=>f.edgeNontransparent===0),
  seamlessEndpoints:all.idle[0].equals(all.idle[7])&&all.idle[0].equals(all.think[0])&&all.idle[0].equals(all.think[11]),
  autoStartsThinkAt3Seconds:clips.idle.delay.reduce((a,b)=>a+b,0)*2===3000,
  gifsContainExpectedFrames:qa.gifs.idle.pages===8&&qa.gifs.think.pages===12
 };
 fs.writeFileSync(path.join(root,'QA','export-checks.json'),JSON.stringify(qa,null,2));
 console.log(JSON.stringify({root,checks:qa.checks,clipDurations:Object.fromEntries(Object.entries(manifest.clips).map(([k,v])=>[k,v.durationMs])),gifs:Object.fromEntries(Object.entries(qa.gifs).map(([k,v])=>[k,{pages:v.pages,delay:v.delay,width:v.width,pageHeight:v.pageHeight}]))},null,2));
 if(Object.values(qa.checks).some(v=>v!==true))process.exitCode=1;
})().catch(e=>{console.error(e);process.exit(1)});

